local sync = {
    udid = requestMeta.DeviceId,
    idfa = requestMeta.IdFa,
    os_version = requestMeta.mSystemMetas.OS,
    app_version = CS.UnityEngine.Application.version,
    version = requestMeta.ResourceVersion,
    channel = requestMeta.ChannelId,
    imei = requestMeta.DeviceId,
    android_id = requestMeta.DeviceId,
} ---需要同步的数据

local function getChannelId()
    local version = appEngine.GetAppBundleVersion()
    local channelId = version.ChannelId
    return checkInt(channelId)
end
local function IsForeignSDK()
    local channelId = getChannelId()
    return channelId >= 5000
end
local function isOfficialSDK()
    local channelId = getChannelId()
    ---故意给一个大区间用来做为官方服渠道判断
    return (channelId >= 1000 and channelId <= 3999)
end

local function IsBilibiliSDK()
    local channelId = getChannelId()
    ---故意给一个大区间用来做为官方服渠道判断
    return (channelId == 999)
end

local function IsCommonSDK()
    ---故意给一个大区间用来做为官方服渠道判断
    return isOfficialSDK() or IsBilibiliSDK() or IsForeignSDK()
end

local function serialize(t)
    local _json = require('rapidjson')
    return _json.encode(t)
end
local function IsZm()
    local channelId = GameUtils.GetChannelId()
    if channelId == 5033 or channelId == 5035 then
        return true
    end
    return false
end

---setUserPlayer
---设置玩家的信息
---@param t table
function xRecord.setUserPlayer(t)
    if t.openId then
        sync.open_id = tostring(t.openId)
    end
    if t.userId then
        sync.user_id = tostring(t.userId)
    end
    if t.playerId then
        sync.player_id = tostring(t.playerId)
    end
    if t.serverId then
        sync.server = tostring(t.serverId)
    end
    if t.playerLevel then
        sync.player_level = tostring(t.playerLevel)
    end
    XRecordSyncer.SetUserInfo(t)
end

