---record_internal
---共同调用
---@param event_id string
---@param event_content string
function xRecord.record_internal(event_id, event_content)
    if event_content == nil then
        event_content = ''
    end
    if IsCommonSDK() then
        if kTool.IsMobile() then
            table.merge(sync, { event_id = tostring(event_id), event_content = tostring(event_content) })
            SDKCenter.InvokePlugin(ProxyPluginName, "customEvent", serialize(sync))
        else
            XRecordSyncer.Record(event_id, event_content)
        end
    else
        XRecordSyncer.Record(event_id, event_content)
    end
end

---record_internal
---共同调用
---@param event_id string
---@param event_content table 类型
function xRecord.af_internal(event_id, event_content)
    if isNull(event_content) or (type(event_content) ~= "table" ) then
        event_content = {}
    end
    if IsCommonSDK() then
        if kTool.IsMobile() then
            ---@type PlayerComponent
            local playerComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
            if isNotNull(playerComp) then
                event_content.playerId = tostring(playerComp.playerDojo.playerId) 
            end
            -- 全部转化为strig 类型 方式上传事件报错
            for k, v in pairs(event_content) do
                event_content[k] = tostring(v)
            end
            SDKCenter.InvokePlugin(ProxyPluginName, "trackEvent", serialize({ event = tostring(event_id), values = event_content }))
        end
    end
end
---record_internal
---共同调用
---@param event_id string
---@param event_content table 类型
function xRecord.facebook_internal(event_id, event_content)
    if type(event_content) ~= "table"  then
        return
    end
    if (not IsZm()) and (not kTool.IsMobile()) then
        return 
    end
    -- 全部转化为strig 类型 方式上传事件报错
    for k, v in pairs(event_content) do
        event_content[k] = tostring(v)
    end
    SDKCenter.InvokePlugin(ProxyPluginName, "facebookEvent", serialize({ event = tostring(event_id), values = event_content }))
end

function xRecord.adjust_internal(event_content)
    if type(event_content) ~= "table"  then
        return
    end

    if not adjust_event_android[event_content.event] then
        return
    end

    if (not IsZm()) and (not kTool.IsMobile()) then
       return 
    end

    if event_content.event == adjust_event_android.first_login then
        local isFirst = CfUtils.GetLocalData("first_login" ,"0")
        if checkInt(isFirst) > 0 then
            return
        end
        CfUtils.WriteLocalData("first_login" ,"1")
    end
  -- 全部转化为strig 类型 方式上传事件报错
    for k, v in pairs(event_content) do
        event_content[k] = tostring(v)
    end
    if kTool.UNITY_ANDROID() then
        table.merge(event_content, adjust_event_android[event_content.event])    
    elseif kTool.UNITY_IOS() then
        table.merge(event_content, adjust_event_ios[event_content.event])    
    end
    SDKCenter.InvokePlugin(ProxyPluginName, "adjustEvent", serialize(event_content))
end

---record
---记录数据
---@param event_id string
---@param event_content string
function xRecord.record(event_id, event_content)
    local t
    if events[tostring(event_id)] then
        t = events[tostring(event_id)]
        if not event_content then
            event_content = t.event_content
        end
        xRecord.record_internal(t.event_id, event_content)
    else
        xRecord.record_internal(event_id, event_content)
    end
end

return xRecord